<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { anularMovimiento, buscarCuentasMovimiento, detalleMovimiento, guardarMovimiento, listarMovimientos, listarNumeracionesMovimiento, listarTiposDocumentoMovimiento } from '../services/movimientosContables'
import type { CuentaMovimiento, DetalleMovimiento, FiltrosMovimiento, MovimientoContable, MovimientoPayload, OpcionesMovimiento } from '../interfaces/movimientosContables.interface'
const emptyOptions=():OpcionesMovimiento=>({periodos:[],tipos_comprobante:[],origenes:[],monedas:[],sucursales:[],tipos_documento:[],numeraciones:[]})
const blankLine=(tipo:'D'|'H'='D'):DetalleMovimiento=>({cuenta_contable_id:0,cuenta:null,centro_costo_id:null,req_cod_trabajador:null,req_cod_proveedor:null,req_cod_inv:null,req_cod_entidad:null,costo_abc_a:null,importe:0,tipo,glosa:''})
const blank=():MovimientoPayload=>({tipo_comprobante_id:0,origen_comprobante_id:0,numeracion_comprobantes_id:0,sucursal_id:0,moneda_id:0,tipo_documento_id:0,detalle_periodo_id:0,fecha_comprobante:new Date().toISOString().slice(0,10),glosa:'',detalles:[blankLine('D'),blankLine('H')]})
const rows=ref<MovimientoContable[]>([]),options=ref<OpcionesMovimiento>(emptyOptions()),page=ref(1),lastPage=ref(1),total=ref(0),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),modal=ref(false),viewModal=ref(false),editing=ref<number|null>(null),selected=ref<MovimientoContable|null>(null),accountQuery=ref(''),accounts=ref<CuentaMovimiento[]>([]),lineIndex=ref(0)
const filters=reactive<FiltrosMovimiento>({detalle_periodo_id:'',cuenta_contable_id:'',origen_comprobante_id:'',tipo_comprobante_id:'',tipo_documento_id:'',fecha_desde:'',fecha_hasta:'',estado:''}),form=reactive<MovimientoPayload>(blank())
const totalDebe=computed(()=>form.detalles.filter(x=>x.tipo==='D').reduce((a,b)=>a+Number(b.importe||0),0)),totalHaber=computed(()=>form.detalles.filter(x=>x.tipo==='H').reduce((a,b)=>a+Number(b.importe||0),0)),balanced=computed(()=>totalDebe.value>0&&Math.abs(totalDebe.value-totalHaber.value)<=.01)
const message=(v:unknown)=>v instanceof Error?v.message:'No se pudo completar la operación.'
async function load(next=1){loading.value=true;error.value='';try{const r=await listarMovimientos(filters,next);rows.value=r.data;options.value=r.options;page.value=r.current_page;lastPage.value=r.last_page;total.value=r.total}catch(v){error.value=message(v)}finally{loading.value=false}}
function clear(){Object.keys(filters).forEach(k=>filters[k as keyof FiltrosMovimiento]='');load(1)}
function open(){editing.value=null;Object.assign(form,blank());modal.value=true}
async function show(item:MovimientoContable){try{selected.value=await detalleMovimiento(item.id);viewModal.value=true}catch(v){error.value=message(v)}}
async function changeType(){form.tipo_documento_id=0;form.numeracion_comprobantes_id=0;options.value.tipos_documento=form.tipo_comprobante_id?await listarTiposDocumentoMovimiento(form.tipo_comprobante_id):[]}
async function changeNumber(){form.numeracion_comprobantes_id=0;options.value.numeraciones=form.tipo_documento_id&&form.detalle_periodo_id?await listarNumeracionesMovimiento(form.tipo_documento_id,form.detalle_periodo_id):[]}
function addLine(){form.detalles.push(blankLine(form.detalles.at(-1)?.tipo==='D'?'H':'D'))} function removeLine(i:number){if(form.detalles.length>2)form.detalles.splice(i,1)}
async function searchAccount(i:number){if(accountQuery.value.trim().length<3)return void(error.value='Ingrese al menos 3 caracteres para buscar una cuenta.');lineIndex.value=i;try{accounts.value=await buscarCuentasMovimiento(accountQuery.value.trim())}catch(v){error.value=message(v)}}
function chooseAccount(c:CuentaMovimiento){const line=form.detalles[lineIndex.value];if(line){line.cuenta_contable_id=c.id;line.cuenta=c}accounts.value=[];accountQuery.value=''}
async function save(){if(!form.tipo_comprobante_id||!form.origen_comprobante_id||!form.moneda_id||!form.sucursal_id||!form.tipo_documento_id||!form.detalle_periodo_id||!form.numeracion_comprobantes_id)return void(error.value='Complete todos los datos obligatorios del comprobante.');if(form.detalles.some(x=>!x.cuenta_contable_id||Number(x.importe)<=0))return void(error.value='Cada detalle requiere cuenta contable e importe mayor a cero.');if(!balanced.value)return void(error.value=`El Debe (${totalDebe.value.toFixed(2)}) y el Haber (${totalHaber.value.toFixed(2)}) deben coincidir.`);saving.value=true;try{await guardarMovimiento(editing.value,form);modal.value=false;success.value='Movimiento contable registrado correctamente.';await load(1)}catch(v){error.value=message(v)}finally{saving.value=false}}
async function cancel(item:MovimientoContable){if(!confirm(`¿Anular el movimiento ${item.numero_comprobante}?`))return;try{await anularMovimiento(item.id);success.value='Movimiento anulado correctamente.';await load(page.value)}catch(v){error.value=message(v)}}
onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / <RouterLink to="/modulos/administracion/contabilidad">Contabilidad</RouterLink> / Movimientos contables</nav><header class="hero"><div class="mark">MC</div><div><small>MIA · CONTABILIDAD · MOVIMIENTOS</small><h1>Movimientos contables</h1><p>Registra y consulta comprobantes con asientos balanceados al Debe y Haber.</p></div><strong>{{total}} movimientos</strong><button @click="open">+ Nuevo movimiento</button></header><p v-if="success" class="flash success">✓ {{success}}</p><p v-if="error" class="flash error">{{error}}</p><form class="filters" @submit.prevent="load(1)"><select v-model="filters.detalle_periodo_id"><option value="">Todos los periodos</option><option v-for="o in options.periodos" :key="o.id" :value="o.id">{{o.codigo||o.nombre}} - {{o.nombre}}</option></select><select v-model="filters.origen_comprobante_id"><option value="">Todos los orígenes</option><option v-for="o in options.origenes" :key="o.id" :value="o.id">{{o.nombre}}</option></select><select v-model="filters.tipo_comprobante_id"><option value="">Todos los tipos</option><option v-for="o in options.tipos_comprobante" :key="o.id" :value="o.id">{{o.nombre}}</option></select><input v-model="filters.fecha_desde" type="date"><input v-model="filters.fecha_hasta" type="date"><select v-model="filters.estado"><option value="">Todos los estados</option><option value="1">Activos</option><option value="0">Anulados</option></select><button>Buscar</button><button type="button" class="soft" @click="clear">Limpiar</button></form><section class="table-card"><div v-if="loading" class="empty">Consultando movimientos…</div><div v-else-if="!rows.length" class="empty">No se encontraron movimientos contables.</div><div v-else class="scroll"><table><thead><tr><th>#</th><th>Movimiento</th><th>Fecha</th><th>Tipo</th><th>Documento</th><th>Origen</th><th>Glosa</th><th>Periodo</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><tr v-for="item in rows" :key="item.id"><td>{{item.id}}</td><td><b>{{item.numero_comprobante}}</b></td><td>{{item.fecha_comprobante}}</td><td>{{item.tipo_comprobante?.nombre||'—'}}</td><td>{{item.tipo_documento?.nombre||'—'}}</td><td>{{item.origen?.nombre||'—'}}</td><td>{{item.glosa||'—'}}</td><td>{{item.periodo?.nombre||'—'}}</td><td><span :class="item.estado?'ok':'bad'">{{item.estado?'Activo':'Anulado'}}</span></td><td class="actions"><button class="edit" @click="show(item)">Ver</button><a v-if="item.asiento_pdf_url" :href="item.asiento_pdf_url" target="_blank">PDF</a><button v-if="item.estado" class="soft" @click="cancel(item)">Anular</button></td></tr></tbody></table></div><footer v-if="lastPage>1"><button :disabled="page<=1" @click="load(page-1)">Anterior</button><span>{{page}} / {{lastPage}}</span><button :disabled="page>=lastPage" @click="load(page+1)">Siguiente</button></footer></section><div v-if="modal" class="backdrop" @mousedown.self="modal=false"><form class="dialog" @submit.prevent="save"><header><div><small>MOVIMIENTO CONTABLE</small><h2>Nuevo comprobante</h2></div><button type="button" @click="modal=false">×</button></header><div class="grid"><label>Tipo comprobante *<select v-model.number="form.tipo_comprobante_id" @change="changeType"><option :value="0">Seleccione</option><option v-for="o in options.tipos_comprobante" :key="o.id" :value="o.id">{{o.nombre}}</option></select></label><label>Tipo documento *<select v-model.number="form.tipo_documento_id" @change="changeNumber"><option :value="0">Seleccione</option><option v-for="o in options.tipos_documento" :key="o.id" :value="o.id">{{o.nombre}}</option></select></label><label>Origen *<select v-model.number="form.origen_comprobante_id"><option :value="0">Seleccione</option><option v-for="o in options.origenes" :key="o.id" :value="o.id">{{o.nombre}}</option></select></label><label>Moneda *<select v-model.number="form.moneda_id"><option :value="0">Seleccione</option><option v-for="o in options.monedas" :key="o.id" :value="o.id">{{o.nombre}}</option></select></label><label>Sucursal *<select v-model.number="form.sucursal_id"><option :value="0">Seleccione</option><option v-for="o in options.sucursales" :key="o.id" :value="o.id">{{o.nombre}}</option></select></label><label>Periodo *<select v-model.number="form.detalle_periodo_id" @change="changeNumber"><option :value="0">Seleccione</option><option v-for="o in options.periodos" :key="o.id" :value="o.id">{{o.nombre}}</option></select></label><label>Numeración *<select v-model.number="form.numeracion_comprobantes_id"><option :value="0">Seleccione</option><option v-for="o in options.numeraciones" :key="o.id" :value="o.id">{{o.nombre}}</option></select></label><label>Fecha *<input v-model="form.fecha_comprobante" type="date"></label><label class="span2">Glosa<textarea v-model="form.glosa" maxlength="500"></textarea></label></div><div class="details-head"><h3>Detalle de cuentas</h3><button type="button" @click="addLine">+ Agregar línea</button></div><div class="scroll"><table class="details"><thead><tr><th>Cuenta</th><th>Glosa</th><th>Tipo</th><th>Importe</th><th></th></tr></thead><tbody><tr v-for="(line,i) in form.detalles" :key="i"><td><span v-if="line.cuenta"><b>{{line.cuenta.cta_contable}}</b> {{line.cuenta.descripcion}}</span><div class="account"><input v-model="accountQuery" placeholder="Buscar cuenta"><button type="button" @click="searchAccount(i)">Buscar</button></div></td><td><input v-model="line.glosa" maxlength="200"></td><td><select v-model="line.tipo"><option value="D">Debe</option><option value="H">Haber</option></select></td><td><input v-model.number="line.importe" type="number" min="0.01" step="0.01"></td><td><button type="button" class="soft" @click="removeLine(i)">×</button></td></tr></tbody></table></div><div v-if="accounts.length" class="results"><button v-for="c in accounts" :key="c.id" type="button" @click="chooseAccount(c)"><b>{{c.cta_contable}}</b> {{c.descripcion}}</button></div><div class="totals" :class="{unbalanced:!balanced}"><span>Debe: S/ {{totalDebe.toFixed(2)}}</span><span>Haber: S/ {{totalHaber.toFixed(2)}}</span><b>{{balanced?'Balanceado':'Diferencia: S/ '+Math.abs(totalDebe-totalHaber).toFixed(2)}}</b></div><footer><button type="button" class="soft" @click="modal=false">Cancelar</button><button :disabled="saving||!balanced">Guardar movimiento</button></footer></form></div><div v-if="viewModal&&selected" class="backdrop" @mousedown.self="viewModal=false"><article class="dialog"><header><h2>Movimiento {{selected.numero_comprobante}}</h2><button @click="viewModal=false">×</button></header><p>{{selected.glosa||'Sin glosa'}}</p><div class="scroll"><table class="details"><thead><tr><th>Cuenta</th><th>Glosa</th><th>Debe</th><th>Haber</th></tr></thead><tbody><tr v-for="d in selected.detalles" :key="d.id"><td>{{d.cuenta?.cta_contable}} - {{d.cuenta?.descripcion}}</td><td>{{d.glosa}}</td><td>{{d.tipo==='D'?Number(d.importe).toFixed(2):'—'}}</td><td>{{d.tipo==='H'?Number(d.importe).toFixed(2):'—'}}</td></tr></tbody></table></div></article></div></div></template>
<style scoped>
.page{--a:#385d8a;color:#35464e}nav{margin-bottom:16px;color:#929fa5;font-size:.68rem}nav a{color:var(--a);text-decoration:none}.hero{padding:20px;display:flex;align-items:center;gap:14px;border-left:5px solid var(--a);border-radius:12px;background:#fff}.mark{width:48px;height:48px;display:grid;place-items:center;border-radius:10px;color:#fff;background:var(--a);font-weight:800}.hero small,.dialog small{color:var(--a);font-size:.48rem;font-weight:800}.hero h1{margin:2px 0;font-size:1.3rem}.hero p{margin:0;color:#7e8a90;font-size:.67rem}.hero strong{margin-left:auto;font-size:.55rem}.hero button,.filters button,.table-card footer button,.dialog button{padding:9px 12px;border:0;border-radius:6px;color:#fff;background:var(--a);font-size:.52rem}.flash{padding:9px;border-radius:7px;font-size:.6rem}.success{color:#287052;background:#edf9f3}.error{color:#a64046;background:#fff0f0}.filters{margin-top:10px;padding:13px;display:grid;grid-template-columns:repeat(4,1fr);gap:7px;background:#fff}.filters input,.filters select,.dialog input,.dialog select,.dialog textarea{width:100%;box-sizing:border-box;padding:8px;border:1px solid #d7dfe2;border-radius:6px;font:inherit;font-size:.53rem;background:#fff}.soft{color:#64727a!important;background:#edf1f3!important}.table-card{margin-top:10px;background:#fff;overflow:hidden}.scroll{overflow:auto}table{width:100%;min-width:970px;border-collapse:collapse;font-size:.5rem}th,td{padding:9px;border-bottom:1px solid #e8ecee;text-align:left}th{color:#fff;background:#4c627e}.ok,.bad{padding:4px 7px;border-radius:10px;font-size:.43rem}.ok{color:#287154;background:#e6f7ee}.bad,.unbalanced{color:#9d4046;background:#fdebed}.actions{display:flex;gap:4px}.actions button,.actions a{padding:6px;border:0;border-radius:5px;font-size:.44rem;text-decoration:none}.edit{color:#385d8a;background:#e8eff8}.empty{padding:45px;text-align:center}.table-card>footer{padding:10px;display:flex;justify-content:center;gap:9px}.backdrop{position:fixed;z-index:100;inset:0;padding:14px;display:grid;place-items:center;background:#172b3d88}.dialog{width:min(1050px,100%);max-height:94vh;overflow:auto;padding:20px;box-sizing:border-box;border-radius:12px;background:#fff}.dialog>header{display:flex;justify-content:space-between}.dialog h2{margin:3px 0 14px;font-size:.9rem}.dialog>header button{color:#59666c;background:none;font-size:1.1rem}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:9px}.dialog label{display:grid;gap:4px;font-size:.48rem}.span2{grid-column:span 2}.details-head{display:flex;align-items:center;justify-content:space-between;margin-top:14px}.details{min-width:780px}.account{display:flex;gap:4px;margin-top:4px}.results{display:grid;max-height:140px;overflow:auto}.results button{text-align:left;color:#35464e;background:#f1f5f7}.totals{margin-top:10px;padding:10px;display:flex;justify-content:flex-end;gap:20px;background:#e8f7ef;font-size:.58rem}.dialog>footer{margin-top:14px;display:flex;justify-content:flex-end;gap:6px}@media(max-width:800px){.hero{flex-wrap:wrap}.hero strong{margin-left:0}.filters,.grid{grid-template-columns:1fr 1fr}}@media(max-width:520px){.filters,.grid{grid-template-columns:1fr}.span2{grid-column:auto}}
</style>
